import heapq


def runningPercentile(nums, p):
    lo, hi = [], []  # lo: max-heap (negated) with the r smallest, hi: min-heap with the rest
    out = []
    for m, x in enumerate(nums, 1):
        if lo and x > -lo[0]:
            heapq.heappush(hi, x)
        else:
            heapq.heappush(lo, -x)
        r = (p * m + 99) // 100
        while len(lo) > r:
            heapq.heappush(hi, -heapq.heappop(lo))
        while len(lo) < r:
            heapq.heappush(lo, -heapq.heappop(hi))
        out.append(-lo[0])
    return out
